package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func check(solve string) string {
	if len(solve) > 0 {
		if solve[0] == '.' {
			solve = "dot" + solve[1:]
		} else if solve[0] == '@' {
			solve = "at" + solve[1:]
		}
	}
	if len(solve) > 0 {
		last := solve[len(solve)-1]
		if last == '.' {
			solve = solve[:len(solve)-1] + "dot"
		} else if last == '@' {
			solve = solve[:len(solve)-1] + "at"
		}
	}
	return solve
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	var s string
	if scanner.Scan() {
		s = scanner.Text()
	}

	var solve strings.Builder
	n := len(s)
	for i := 0; i < n; {
		if i+3 <= n && s[i:i+3] == "dot" {
			solve.WriteByte('.')
			i += 3
		} else if i+2 <= n && s[i:i+2] == "at" {
			solve.WriteByte('@')
			i += 2
		} else {
			solve.WriteByte(s[i])
			i++
		}
	}

	solveStr := check(solve.String())

	count := strings.Count(solveStr, "@")

	if count == 1 {
		fmt.Println(solveStr)
	} else {
		var out strings.Builder
		firstAt := true
		for i := 0; i < len(solveStr); i++ {
			if solveStr[i] == '@' {
				if firstAt {
					out.WriteByte('@')
					firstAt = false
				} else {
					out.WriteString("at")
				}
			} else {
				out.WriteByte(solveStr[i])
			}
		}
		fmt.Println(out.String())
	}
}

